:root{font-family:Inter,Arial,sans-serif;color:#eee;background:#111}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top,#24201a,#111 42%);min-height:100vh}main{max-width:1000px;margin:0 auto;padding:28px 18px 60px}h1{margin:0 0 5px;font-size:28px;color:#f4b23e}.sub{margin:0 0 22px;color:#bbb}.card{border:1px solid #4c4335;background:#191713;border-radius:12px;padding:18px;margin:14px 0;box-shadow:0 8px 28px #0005}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.metric{background:#242019;border:1px solid #3f372c;border-radius:9px;padding:12px}.metric span{display:block;color:#aaa;font-size:12px}.metric strong{display:block;margin-top:4px;font-size:22px}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.grow{flex:1 1 300px}button,select{border:1px solid #80662e;background:#2a2419;color:#fff;border-radius:8px;padding:9px 13px;font:inherit}button{cursor:pointer}button.primary{background:#8b5e10;border-color:#d69a24}button:disabled{opacity:.45;cursor:not-allowed}progress{width:100%;height:18px;accent-color:#d69a24}.status{white-space:pre-wrap;background:#0d0d0d;border:1px solid #333;border-radius:8px;padding:12px;min-height:72px;font-family:ui-monospace,Consolas,monospace;font-size:13px;color:#ddd}.note{color:#aaa;font-size:13px;line-height:1.45}.warn{color:#ffcc72}.ok{color:#8fe19c}.bad{color:#ff8c8c}#authBox{display:none}.hidden{display:none!important}
